import pandas as pd
import matplotlib.pyplot as plt
import os

# 1. Load the data
# Replace this with the actual path generated by your simulation
data_path = "resources/data/simulation_20251215_222628/particle_trajectory.csv"

if not os.path.exists(data_path):
    print("File not found. Please check the directory.")
else:
    df = pd.read_csv(data_path)

    # 2. Setup Plot
    plt.figure(figsize=(8, 8))

    # Plot Trajectory
    plt.plot(df['x'], df['y'], label='Orbit', linewidth=1.5)

    # Mark Start and End
    plt.scatter(df['x'].iloc[0], df['y'].iloc[0], color='green', label='Start', zorder=5)
    plt.scatter(df['x'].iloc[-1], df['y'].iloc[-1], color='red', label='End', zorder=5)

    # Mark Center (0,0)
    plt.scatter(0, 0, marker='+', color='black', s=100, label='Center Potential')

    # Formatting
    plt.xlabel('x [kpc]')
    plt.ylabel('y [kpc]')
    plt.title('Single Particle Trajectory')
    plt.axis('equal')  # Important for correct orbit shape perception
    plt.grid(True, alpha=0.3)
    plt.legend()

    plt.show()